import { posix } from "node:path";
import type { ClaimReading, RawClaim } from "./role-generator-claims.js";

/**
 * Commands in the repository's own scripts (package.json scripts, Makefile, justfile, Taskfile, shell scripts, CI workflows, tox) that run
 * a known generator with an output path: `openapi-python-client generate --output-path src/x`, `protoc --python_out=gen`,
 * `openapi-typescript spec.json -o src/schema.ts`. The owner wrote the command, so the path it names is generated by their declaration.
 * A second kind is a freshness check (`git diff --exit-code <path>`) in a file that also runs a generator step: the repository regenerates
 * that path and fails when it differs. A comment line, a mention of a tool without an output flag, a variable path and an output of an
 * unrelated tool are not evidence. Output paths are resolved against the tracked files by `resolveClaims`.
 */
interface ToolSpec { tool: string; detect: RegExp; outputs: RegExp; }

const SHORT_OUT = "(?:^|\\s)(?:-o|--output|--out)(?:=|\\s+)(\\S+)";
const SPECS: readonly ToolSpec[] = [
	{ tool: "openapi-python-client", detect: /\bopenapi-python-client\b[^|;&]*\bgenerate\b/, outputs: /--output-path(?:=|\s+)(\S+)/g },
	{ tool: "openapi-generator", detect: /\bopenapi-generator[\w.-]*[^|;&]*\bgenerate\b/, outputs: new RegExp(SHORT_OUT, "g") },
	{ tool: "openapi-typescript", detect: /\bopenapi-typescript\b/, outputs: new RegExp(SHORT_OUT, "g") },
	{ tool: "swagger-typescript-api", detect: /\bswagger-typescript-api\b/, outputs: new RegExp(SHORT_OUT, "g") },
	{ tool: "protoc", detect: /\b(?:protoc|grpc_tools\.protoc|grpc_tools_node_protoc)\b/, outputs: /--[a-z0-9_+-]*_out(?:=|\s+)(?:[^:\s]*:)?(\S+)/g },
	{ tool: "datamodel-codegen", detect: /\bdatamodel-codegen\b/, outputs: new RegExp(SHORT_OUT, "g") },
	{ tool: "quicktype", detect: /\bquicktype\b/, outputs: new RegExp(SHORT_OUT, "g") },
	{ tool: "json-schema-to-typescript", detect: /\bjson2ts\b|\bjson-schema-to-typescript\b/, outputs: new RegExp(SHORT_OUT, "g") },
	{ tool: "supabase gen types", detect: /\bsupabase\s+gen\s+types\b/, outputs: />\s*(\S+)/g },
	{ tool: "oapi-codegen", detect: /\boapi-codegen\b/, outputs: /(?:\s-o|--output)(?:=|\s+)(\S+)|>\s*(\S+)/g },
	{ tool: "mockgen", detect: /\bmockgen\b/, outputs: /-destination(?:=|\s+)(\S+)/g },
	{ tool: "thrift", detect: /\bthrift\b[^|;&]*--gen\b/, outputs: /\s-out\s+(\S+)/g },
	{ tool: "flatc", detect: /\bflatc\b/, outputs: /\s-o\s+(\S+)/g },
	{ tool: "kysely-codegen", detect: /\bkysely-codegen\b/, outputs: /--out-file(?:=|\s+)(\S+)/g },
];

const COMMAND_SOURCE = /(?:^|\/)(?:package\.json|Makefile|makefile|GNUmakefile|[\w.-]+\.mk|justfile|Justfile|Taskfile\.ya?ml|tox\.ini|noxfile\.py|\.gitlab-ci\.yml|[\w.-]+\.sh)$|(?:^|\/)\.github\/workflows\/[\w.-]+\.ya?ml$/;
export const isCommandSourceName = (file: string): boolean => COMMAND_SOURCE.test(file);

interface Logical { text: string; line: number; segments: Array<{ from: number; line: number }>; }

/** The logical command lines of a script (backslash continuations joined), each with the physical line of every part. */
function logicalLines(text: string): Logical[] {
	const result: Logical[] = [], physical = text.split("\n");
	for (let at = 0; at < physical.length; at++) {
		const current: Logical = { text: "", line: at + 1, segments: [] };
		for (let part = physical[at] ?? ""; ; part = physical[at] ?? "") {
			current.segments.push({ from: current.text.length, line: at + 1 });
			const continued = part.endsWith("\\");
			current.text += continued ? `${part.slice(0, -1)} ` : part;
			if (!continued || at + 1 >= physical.length) break;
			at++;
		}
		result.push(current);
	}
	return result;
}

function packageScripts(text: string): Logical[] {
	try {
		const scripts: unknown = (JSON.parse(text) as { scripts?: unknown }).scripts;
		if (scripts === null || typeof scripts !== "object") return [];
		const physical = text.split("\n");
		return Object.entries(scripts as Record<string, unknown>).filter((entry): entry is [string, string] => typeof entry[1] === "string").map(([name, command]) => {
			const line = Math.max(1, physical.findIndex((candidate) => candidate.includes(`"${name}"`)) + 1);
			return { text: command, line, segments: [{ from: 0, line }] };
		});
	} catch { return []; }
}

const lineOf = (logical: Logical, offset: number): number => logical.segments.filter((segment) => segment.from <= offset).at(-1)?.line ?? logical.line;
const clean = (value: string): string => value.replace(/^['"]+|['"`;,)]+$/g, "").replace(/^['"]+/, "");
const isComment = (text: string): boolean => /^\s*(?:#|\/\/|-?\s*name\s*:)/.test(text);

function scriptDirs(file: string): { base: string; fallback: string[] } {
	const dir = posix.dirname(file) === "." ? "" : posix.dirname(file);
	return { base: dir, fallback: dir === "" ? [] : [posix.dirname(dir) === "." ? "" : posix.dirname(dir)] };
}

function fromLogical(file: string, logical: Logical): RawClaim[] {
	if (isComment(logical.text)) return [];
	const { base, fallback } = scriptDirs(file), claims: RawClaim[] = [];
	for (const spec of SPECS) {
		if (!spec.detect.test(logical.text)) continue;
		for (const found of logical.text.matchAll(spec.outputs)) {
			const path = clean(found[1] ?? found[2] ?? "");
			if (path !== "" && !path.startsWith("-")) claims.push({ tool: spec.tool, path, baseDir: base, fallbackDirs: fallback, file, line: lineOf(logical, found.index ?? 0), kind: "generator-command" });
		}
	}
	return claims;
}

const FRESHNESS = /\bgit\s+diff\b[^|;&]*(?:--exit-code|--quiet)\b([^|;&]*)/;
const GENERATOR_CONTEXT = /\b(?:generate|codegen|gen)\b/i;
const FRESHNESS_WINDOW = 12;

function freshness(file: string, logicals: readonly Logical[], index: number): RawClaim[] {
	const current = logicals[index];
	if (current === undefined || isComment(current.text)) return [];
	const found = FRESHNESS.exec(current.text);
	if (found === null) return [];
	const near = logicals.slice(Math.max(0, index - FRESHNESS_WINDOW), index + FRESHNESS_WINDOW + 1);
	if (!near.some((other) => other !== current && !isComment(other.text) && (SPECS.some((spec) => spec.detect.test(other.text)) || GENERATOR_CONTEXT.test(other.text)))) return [];
	const { base, fallback } = scriptDirs(file), artifacts = near.flatMap((other) => /\bpath:\s*(\S+)/.exec(other.text)?.[1] ?? []).map(clean);
	const named = (found[1] ?? "").split(/\s+/).map(clean).filter((token) => token !== "" && token !== "--" && !token.startsWith("-") && token !== "HEAD");
	// A check on a directory covers what the job regenerates: when the same job uploads a sub-directory of it as the generated artifact, that sub-directory is the claim.
	return named.flatMap((path) => { const narrower = artifacts.filter((artifact) => artifact.startsWith(`${path}/`)); return narrower.length > 0 ? narrower : [path]; })
		.map((path) => ({ tool: "freshness-check", path, baseDir: base, fallbackDirs: fallback, file, line: current.line, kind: "generator-command" as const }));
}

const SCRIPT_FILE = /\.(?:sh|bash|py)$|(?:^|\/)(?:Makefile|makefile|justfile)$/;
const ASSIGNMENT = /^\s*(?:export\s+|readonly\s+)?([A-Za-z_]\w*)\s*=\s*(?:Path\(\s*|os\.path\.join\(\s*)?(?:"([^"\n]*)"|'([^'\n]*)')/;
const OUTPUT_NAME = /(?:^|_)(?:out|output)(?:_(?:dir|path|directory|folder|root))?$/i;
const SCRATCH_NAME = /tmp|temp/i;
const VARIABLE = /\$\{(\w+)\}|\$(\w+)/g;

/** A literal with the script's own literal variables substituted; an unresolved leading variable (`$ROOT/`) is dropped, any other is not guessed. */
function substituted(value: string, known: ReadonlyMap<string, string>): string | null {
	let text = value;
	for (let round = 0; round < 5 && /\$/.test(text); round++) text = text.replace(VARIABLE, (whole, a: string | undefined, b: string | undefined) => known.get(a ?? b ?? "") ?? whole);
	const stripped = text.replace(/^\$\{?\w+\}?\//, "");
	return /[$`]/.test(stripped) ? null : stripped;
}

/**
 * A script that runs a known generator names where the result goes in a variable that is assigned a literal (`output_path = Path("src/api")`,
 * `OUT_DIR="$PKG/src/gen"`). Only an output-like name counts (not a temp directory, not an input), only in a script that itself runs the
 * generator, and the path must resolve against the tracked files. The script's file name is never evidence.
 */
function scriptOutputVariables(file: string, text: string): RawClaim[] {
	if (!SCRIPT_FILE.test(file)) return [];
	const code = text.split("\n").filter((line) => !/^\s*(?:#|\/\/)/.test(line)).join("\n").replace(/["',()\[\]]/g, " ");
	if (!SPECS.some((spec) => spec.detect.test(code))) return [];
	const known = new Map<string, string>(), found: Array<{ name: string; value: string; line: number }> = [];
	for (const [index, line] of text.split("\n").entries()) {
		const match = ASSIGNMENT.exec(line);
		if (match?.[1] === undefined) continue;
		const value = match[2] ?? match[3] ?? "";
		if (!/\$\(|`/.test(line)) known.set(match[1], substituted(value, known) ?? value);
		if (OUTPUT_NAME.test(match[1]) && !SCRATCH_NAME.test(match[1]) && !SCRATCH_NAME.test(value)) found.push({ name: match[1], value, line: index + 1 });
	}
	const { base, fallback } = scriptDirs(file), tool = SPECS.find((spec) => spec.detect.test(code))?.tool ?? "generator";
	return found.flatMap((item) => {
		const path = substituted(item.value, known);
		return path === null || path === "" ? [] : [{ tool, path, baseDir: base, fallbackDirs: fallback, file, line: item.line, kind: "generator-command" as const }];
	});
}

export function readGeneratorCommands(file: string, text: string): ClaimReading {
	const logicals = file.endsWith("package.json") ? packageScripts(text) : logicalLines(text);
	const all = [...logicals.flatMap((logical, index) => [...fromLogical(file, logical), ...freshness(file, logicals, index)]), ...scriptOutputVariables(file, text)];
	const claims = all.filter((claim) => !/[$`]/.test(claim.path));
	const skipped = all.filter((claim) => /[$`]/.test(claim.path)).map((claim) => ({ file, line: claim.line, tool: claim.tool, reason: "variable-path", pattern: claim.path }));
	return { claims, skipped };
}
